style.css:
@-moz-document domain("wattpad.com") {
/* Backgrounds */
  body,
  .container,
  .panel,
  .main,
  .background,
  .story-parts,
  .story-info,
  .profile-header {
    background-color: #1A0E14 !important;
    color: #F5E6F0 !important;
  }

  /* Links & buttons */
  a,
  .btn,
  button,
  .btn-primary {
    background-color: #E36BAE !important;
    color: #1A0E14 !important;
    border: none !important;
    transition: all 0.3s ease !important;
  }

  a:hover,
  .btn:hover,
  button:hover,
  .btn-primary:hover {
    background-color: #FF8CC6 !important;
    color: #1A0E14 !important;
  }

  /* Text */
  p,
  span,
  h1, h2, h3, h4, h5, h6,
  .text,
  .title {
    color: #F5E6F0 !important;
  }

  /* Subtle elements */
  .footer,
  .meta,
  .comment,
  .secondary-text {
    color: #BFA4B6 !important;
  }

  /* Borders and dividers */
  hr,
  .divider,
  .border,
  .panel,
  input,
  textarea {
    border-color: #6B4E5E !important;
    background-color: #24121B !important;
    color: #F5E6F0 !important;
  }

  /* Reading mode */
  .reading-view,
  .story-page,
  .story-body {
    background-color: #140A10 !important;
    color: #F5E6F0 !important;
  }

  /* Header / navbar */
  header,
  .navbar,
  .nav {
    background-color: #1E0D16 !important;
    color: #F5E6F0 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #1A0E14;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #E36BAE;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: #FF8CC6;
  }
}
